ROWS = [
dict(id="T063", x="SOLVED (claimed, unrefereed), 14 Nov 2026: the OpenAI math release preprint 'The Gaussian free field limit of the balanced six-vertex model with variance multiplier 1/arcsin(c/2)' (23 Sep 2026, Thm 1.1) claims GFF convergence for every 0 < c <= 2 with a = b = 1 in the balanced zero-slope plane state. No Lean file covers it; a November 2026 follow-up by Yan Ru Pei proposes a conditional repair of a gap in the state identification. AI-written and unrefereed; this records the claim, not a check of the proof. Replacement row to be screened.", d="GF", t="Gaussian free field limit of the six-vertex height function",
 s="For the six-vertex model on Z^2 with weights a = b = 1 and c ∈ (0, 2), so that Δ = 1 − c²/2 ∈ (−1, 1), the height function converges in the scaling limit to a Gaussian free field whose variance is an explicit function of Δ.",
 src="R. J. Baxter, Exactly Solved Models in Statistical Mechanics (Academic Press, 1982); B. Nienhuis, Critical behavior of two-dimensional spin models and charge asymmetry in the Coulomb gas, J. Stat. Phys. 34 (1984)",
 why="The six-vertex model contains square ice, the uniform three-colourings and (through the BKW correspondence) the critical FK and Potts models; a GFF limit is the Coulomb-gas prediction behind their exponents.",
 st="Δ = 0 is the dimer model, with GFF limit (Kenyon 2001); small perturbations of it by interacting-dimer methods (Giuliani–Mastropietro–Toninelli, arXiv:1406.7710). For a = b = 1, logarithmic variance (delocalization) for c ∈ [1, 2] (Duminil-Copin–Karrila–Manolescu–Oulamara, arXiv:2012.13750, JEMS 2024), after unbounded variance for c ∈ [√(2+√2), 2] (Lis, arXiv:2004.05337); localization for c > a + b and delocalization at c = a + b (Glazman–Peled, arXiv:1909.03436). Averous–Duminil-Copin–He–Lammers–Manolescu (arXiv:2610.07454) prove convergence to the GFF in simply connected domains with piecewise constant boundary conditions for a wide range of Δ, including Δ near 0 and Δ between −1 and −1/2. The whole range Δ ∈ (−1, 1) is open."),
dict(id="T064", d="GF", t="Percolation description of the nodal lines of random waves (Bogomolny–Schmit)",
 s="The nodal set of the random plane wave (the centred Gaussian field on R^2 with covariance J_0(|x − y|)), and conjecturally of high-energy eigenfunctions of chaotic billiards, has the large-scale behaviour of critical percolation: crossing probabilities of nodal domains converge to Cardy's formula and nodal lines to SLE(6).",
 c="The predicted number of nodal domains per unit area, (3√3 − 5)/π times a normalisation, is off by a few percent in numerics (Nastasescu 2011; Beliaev–Kereta 2013), so the conjecture is the scaling-limit statement, not that constant.",
 src="E. Bogomolny and C. Schmit, Percolation model for nodal domains of chaotic wave functions, Phys. Rev. Lett. 88 (2002); M. V. Berry, Regular and irregular semiclassical wavefunctions, J. Phys. A 10 (1977)",
 why="It ties quantum chaos (Berry's random wave model) to the universality of planar critical percolation, and it is the main test of percolation universality for strongly correlated fields.",
 st="The number of nodal domains grows like a constant times the area (Nazarov–Sodin 2009, 2016). Russo–Seymour–Welsh bounds and sharp thresholds hold for positively correlated planar Gaussian fields with fast decay (Beffara–Gayet 2017; Rivera–Vanneuville 2019; Muirhead–Vanneuville 2020). The random plane wave correlates slowly and changes sign, so none of this applies; open."),
dict(id="T065", d="IPS", t="Hydrodynamic limit of deterministic Hamiltonian dynamics",
 s="For classical particles in R^3 evolving under Newtonian dynamics with a fixed smooth short-range pair potential (or for a non-integrable chain of anharmonic oscillators), started from a local equilibrium state, the conserved fields evolve under Euler scaling by the compressible Euler equations up to the first shock.",
 src="C. B. Morrey, On the derivation of the equations of hydrodynamics from statistical mechanics, Comm. Pure Appl. Math. 8 (1955); S. Olla, S. R. S. Varadhan and H.-T. Yau, Hydrodynamical limit for a Hamiltonian system with weak noise, Comm. Math. Phys. 155 (1993); H. Spohn, Large Scale Dynamics of Interacting Particles (Springer, 1991)",
 why="The derivation of fluid equations from mechanics is the core of Hilbert's sixth problem; every proof so far adds noise to the dynamics to obtain the ergodicity it needs.",
 st="Proved with a small conservative noise (Olla–Varadhan–Yau 1993) and with boundary conditions and conservative noise (Even–Olla, arXiv:1009.2175); derivations through the Boltzmann equation for dilute gases are a separate line (Lanford 1975 and later). Open for deterministic dynamics. See also T033 (Fourier's law).",
 c="Integrable systems (hard rods, the Toda chain, harmonic chains) are excluded: their hydrodynamics is generalised, not Euler. The class of potentials is to fix."),
dict(id="T066", d="COMB", t="The Komlós conjecture",
 s="There is an absolute constant K such that for all vectors v_1, …, v_n ∈ R^m of Euclidean norm at most 1 there are signs ε_i ∈ {−1, 1} with ‖ε_1 v_1 + ⋯ + ε_n v_n‖_∞ ≤ K.",
 src="J. Spencer, Ten Lectures on the Probabilistic Method (SIAM, 1987), where it is attributed to J. Komlós",
 why="The central open problem of discrepancy theory; it implies the Beck–Fiala conjecture, and its best bounds come from Gaussian measure and random-walk arguments.",
 st="Proved: K = 3√(2π) (Guo–Fang–Lu, arXiv:2609.11189), improved to below 6.9013 with a deterministic algorithm (Akbas–Sra, arXiv:2609.27172). Before that: O(√(log n)) (Banaszczyk, Random Structures Algorithms 12 (1998)), algorithmic since 2010 (Bansal; Bansal–Dadush–Garg–Lovett), and roughly (log n)^{1/4} (Bansal–Jiang, STOC 2026).",
 x="SOLVED: Guo–Fang–Lu (arXiv:2609.11189) prove the Komlós conjecture with K = 3√(2π), which also gives the O(√t) Beck–Fiala bound; Akbas–Sra (arXiv:2609.27172) reach 3π, then a constant below 6.9013, with a deterministic algorithm; Bansal (arXiv:2609.33215) is an exposition of the Guo–Fang–Lu algorithm. Read from the arXiv abstract 14 Oct; flagged by the w672 audit."),
dict(id='T067',
 x='SOLVED: The open part of the row (q = 3 and q = 4 at every degree) is stated with proof in two public OpenAI preprints of 25 September and 5 October 2026 (github.com/openai/math, family 229; unrefereed, Lean covers only the above-threshold direction). Independent proofs of ours agree: q = 3 at every d (posted 30 Oct, two audits), q = 4 on the binary tree (posted 7 Nov), and a 24 Oct package for every finite-mean offspring law whose q = 3 and q = 4 certificates were replayed exactly on 3 and 7 Nov. Priority is theirs. What remains new is the finite-mean Galton-Watson case for q = 3 (Formentin-Kulske Conjecture 2.13). Restored if the preprints are withdrawn and our proofs fail.',
 d='TREE',
 t='Tightness of the Kesten–Stigum bound for reconstruction on trees',
 s='For the broadcast process on the d-ary tree (or a Galton–Watson tree with mean d) through the symmetric ferromagnetic q-state Potts channel with second eigenvalue λ > 0, the root can be reconstructed from the far leaves exactly when d λ² > 1 (the Kesten–Stigum bound is tight) for q = 3 and q = 4 and every d; for q ≥ 5 it is not tight.',
 c='The channel must be ferromagnetic: the proper 4-colouring channel (λ = −1/3) on the 9-ary tree has d λ² = 1 and still reconstructs, by the forcing recursion p ↦ 1 − 3(1 − p/3)^9 + 3(1 − 2p/3)^9 − (1 − p)^9, which maps [3/4, 1] into itself (w672 audit, 14 Oct; arithmetic rechecked).',
 src='E. Mossel, Survey: information flow on trees, in Graphs, Morphisms and Statistical Physics (DIMACS Ser. 63, AMS, 2004); A. Sly, Reconstruction for the Potts model, Ann. Probab. 39 (2011)',
 why='Reconstruction thresholds govern phylogenetic reconstruction, Glauber mixing on trees, and the detection thresholds of the stochastic block model, where they separate easy from hard inference.',
 st='q = 2: tight (Bleher–Ruiz–Zagrebnov 1995; Evans–Kenyon–Peres–Schulman 2000). Sly (arXiv:0811.1208) proves tightness for q = 3 on regular trees of large degree and non-tightness for every q ≥ 5. Mossel, Sly and Sohn (arXiv:2212.03362, Theorem 1.12) prove tightness for q = 3 and q = 4 at large mean degree, on regular trees and on Galton–Watson trees whose offspring law satisfies their concentration assumptions. Open for q = 3 and q = 4 at small degree, the binary tree included, and for general Galton–Watson trees.'),
dict(id="T068", d="RG", t="Karp's problem: finding cliques of size (1 + ε) log₂ n in G(n, 1/2)",
 s="For every ε > 0, no polynomial-time algorithm finds a clique of size (1 + ε) log₂ n in G(n, 1/2) with probability bounded away from zero; equivalently, the greedy algorithm's size log₂ n is the algorithmic threshold, half the clique number 2 log₂ n.",
 c="Proving it unconditionally would separate P from NP, so the working form asks for proofs against broad algorithm classes.",
 src="R. M. Karp, The probabilistic analysis of some combinatorial search algorithms, in Algorithms and Complexity: New Directions and Recent Results (Academic Press, 1976)",
 why="The founding example of a statistical-computational gap: a factor of two between what exists and what any known efficient method finds, open since 1976.",
 st="The Metropolis process fails (Jerrum 1992); overlap-gap and low-degree barriers rule out large classes of algorithms in related problems: local algorithms for sparse independent sets (Gamarnik–Sudan, arXiv:1304.1831), planted clique (Gamarnik–Zadik, arXiv:1904.07174), low-degree polynomials for sparse independent sets (Wein, arXiv:2010.06563). Open."),
dict(id="T069", d="RG", t="The storage capacity of the binary perceptron (Krauth–Mézard)",
 s="For the binary perceptron, find σ ∈ {−1, 1}^N with ⟨g_a, σ⟩ ≥ 0 for M = αN iid standard Gaussian vectors g_a; the satisfiability threshold is α_c ≈ 0.833, the value of the Krauth–Mézard replica formula.",
 src="W. Krauth and M. Mézard, Storage capacity of memory networks with binary couplings, J. Phys. France 50 (1989); E. Gardner and B. Derrida, Optimal storage properties of neural network models, J. Phys. A 21 (1988)",
 why="The classical capacity question for neural networks with discrete weights, and a test case for replica predictions in a model with frozen, isolated solutions.",
 st="Claimed proof: the author (arXiv:2607.11010), computer-assisted, Gaussian and subgaussian disorder, awaiting independent reproduction. Before that: the lower bound matching Krauth–Mézard (Ding–Sun 2019), a sharp threshold sequence (Xu 2021), the threshold under a numerical hypothesis (Huang 2024); the symmetric binary perceptron threshold (Perkins–Xu 2021; Abbe–Li–Sly 2022).",
 x="SOLVED (claimed): the author (arXiv:2607.11010) gives a computer-assisted proof, at κ = 0, that the capacity satisfies M_N/N → α_⋆ ∈ [0.833078599, 0.833078600], verifying the Ding–Sun and Huang conditions in Arb interval arithmetic, for Gaussian disorder and for every fixed iid mean-zero unit-variance subgaussian law, Bernoulli included. Reproduced internally and audited by a second system; not yet independently reproduced or peer reviewed (brain memory ising_perceptron_release_verified_2026_07_13). Read from the arXiv abstract 14 Oct."),
dict(id="T070", d="IPS", t="The density conjecture for activated random walk",
 s="For activated random walk on Z^d with sleep rate λ, the critical density ζ_c(λ) of the infinite-volume fixation transition equals the limiting density of the driven-dissipative system run on growing boxes (and of a single-source aggregate), so that the model is self-organised critical at ζ_c.",
 c="The exact list of densities claimed equal is to verify.",
 src="R. Dickman, M. A. Muñoz, A. Vespignani and S. Zapperi, Paths to self-organized criticality, Braz. J. Phys. 30 (2000); L. Levine and V. Silvestri, How far do activated random walkers spread from a single source?, J. Stat. Phys. 185 (2021); L. T. Rolla, Activated random walks on Z^d, Probab. Surv. 17 (2020)",
 why="Activated random walk is the probabilists' model of self-organised criticality, and the density conjecture is the precise form of the claim that a driven-dissipative system tunes itself to the critical point.",
 st="0 < ζ_c < 1 for every λ in every dimension. Positivity: Rolla–Sidoravicius (arXiv:0908.1152) in d = 1, Sidoravicius–Teixeira (arXiv:1412.7098), Stauffer–Taggi (arXiv:1512.02397). ζ_c < 1: Hoffman–Richey–Rolla (arXiv:2009.09491) in d = 1, Taggi (arXiv:1712.05292) in d ≥ 3, small λ in d = 2 (Hu, arXiv:2203.14406; Forien–Gaudillière, arXiv:2203.02476), and every λ in every dimension (Asselah–Forien–Gaudillière, arXiv:2210.04779, Ann. Probab. 2024). In d = 1, Hoffman–Johnson–Junge–Meisel (arXiv:2605.00207) prove self-organised criticality, power-law avalanches and equality with the fixed-energy critical density. Open in d ≥ 2."),
dict(id="T071", d="TREE", t="Branching Brownian motion with selection: the Bolthausen–Sznitman genealogy of N-BBM",
 s="For N-BBM (branching Brownian motion in which, at each branching, the leftmost particle is removed to keep N particles), the genealogy on time scale (log N)³ converges to the Bolthausen–Sznitman coalescent. The Brunet–Derrida speed v_N = v_∞ − c/(log N)² + o((log N)^{−2}) is proved; see where it stands.",
 src="É. Brunet and B. Derrida, Shift in the velocity of a front due to a cutoff, Phys. Rev. E 56 (1997); É. Brunet, B. Derrida, A. H. Mueller and S. Munier, Noisy traveling waves: effect of selection on genealogies, Europhys. Lett. 76 (2006)",
 why="A predicted universality class for populations under selection (and for noisy FKPP fronts), in which the coalescent is not Kingman's.",
 st="Speed: proved for N-BBM (Maillard, arXiv:1304.0562, published 2016) and recovered in a time-inhomogeneous joint limit, log N ≪ T^{1/3} (Legrand–Maillard, arXiv:2402.04917 v4, Theorem 1.1(i) and Corollary 2.1); also for N-branching random walk (Bérard–Gouéré 2010) and noisy FKPP (Mueller–Mytnik–Quastel 2011). Genealogy: proved for BBM with absorption at a moving barrier (Berestycki–Berestycki–Schweinsberg 2013); for N-BBM itself it is open (the w672 audit read Legrand–Maillard in full; no genealogy theorem there)."),
dict(id="T072", d="STAT", t="The planted clique conjecture",
 s="For every fixed ε ∈ (0, 1/2) and k = n^{1/2−ε}, no polynomial-time algorithm distinguishes G(n, 1/2) from G(n, 1/2) with a planted clique of size k with advantage bounded away from zero, and none recovers the planted clique with probability bounded away from zero.",
 c="A proof would imply P ≠ NP, so the realistic targets are restricted models: low-degree polynomials, sum-of-squares, statistical queries, Markov chains.",
 src="M. Jerrum, Large cliques elude the Metropolis process, Random Structures Algorithms 3 (1992); L. Kučera, Expected complexity of graph partitioning problems, Discrete Appl. Math. 57 (1995)",
 why="The reference hypothesis for statistical-computational gaps; hardness for sparse PCA, community detection and many testing problems is proved by reduction from it.",
 st="Solvable for k ≥ c√n (Alon–Krivelevich–Sudakov 1998). Lower bounds for the Metropolis process (Jerrum 1992), statistical-query algorithms (Feldman et al. 2013), sum-of-squares (Barak et al. 2016) and low-degree polynomials (Hopkins 2018). Open, and see T068."),
dict(id="T073", d="IPS", t="Phase transition of the noisy majority vote process on Z^2",
 s="In the majority vote process on Z^2 (each site, at rate one, adopts the majority opinion of its four neighbours with probability 1 − ε and the minority with probability ε, ties broken at random), for ε small enough there are at least two distinct stationary measures.",
 c="The exact update rule used in the literature (neighbourhood, tie-breaking) is to verify.",
 src="T. M. Liggett, Interacting Particle Systems (Springer, 1985); L. F. Gray, The positive rates problem for attractive nearest neighbor spin systems on Z, Z. Wahrsch. Verw. Gebiete 61 (1982)",
 why="A non-reversible relative of the Ising model whose low-noise order is never in doubt in simulations, but whose stationary measures have no Gibbs structure to argue with.",
 st="In one dimension attractive nearest-neighbour systems with positive rates are ergodic (Gray 1982). Toom's anisotropic north-east-centre rule is non-ergodic at low noise (Toom 1980). The general positive-rates conjecture fails (Gács, arXiv:math/0003117, J. Stat. Phys. 103 (2001)). On infinite regular trees the noisy majority vote process has several stationary measures at low noise: Bramson and Gray (2021) for degree at least 5, Ding and Huang (arXiv:2501.16202) for degree at least 3; De Gaspari (arXiv:2508.06935) extends this to graphs with suitable expansion. These arguments use expansion and do not reach Z^2. Open for the symmetric majority rule on Z^2.",
 n="Fame borderline in the w672 audit (14 Oct); kept for now."),
dict(id="T074", d="STAT", t="Complete monotonicity of entropy along the heat flow (McKean; Cheng–Geng)",
 s="For a real random variable X with finite variance and an independent standard Gaussian Z, the function t ↦ h(X + √t Z) satisfies (−1)^{k+1} (d/dt)^k h(X + √t Z) ≥ 0 for every k ≥ 1; and for fixed variance the Gaussian X minimises each of these derivatives in absolute value (McKean's conjecture).",
 src="H. P. McKean, Speed of approach to equilibrium for Kac's caricature of a Maxwellian gas, Arch. Rational Mech. Anal. 21 (1966); F. Cheng and Y. Geng, Higher order derivatives in Costa's entropy power inequality, IEEE Trans. Inform. Theory 61 (2015)",
 why="It would give the whole hierarchy of inequalities of which de Bruijn's identity, Stam's inequality and Costa's concavity of entropy power are the first terms.",
 st="Disproved at k = 5 (Gu–Sellke, arXiv:2605.11656), with log-concave counterexamples in every dimension (Zou–Fan–Gao–Wang, arXiv:2608.30275). Before that: true for k ≤ 4 in one dimension (Cheng–Geng 2015) and for some classes such as Gaussian mixtures.",
 x="DISPROVED: Gu–Sellke (arXiv:2605.11656) give an explicit measure whose fifth entropy derivative along the heat flow has the wrong sign, which also refutes the McKean and Toscani conjectures; Zou–Fan–Gao–Wang (arXiv:2608.30275) give log-concave counterexamples in every dimension. Read from the arXiv abstract 14 Oct; flagged by the w672 audit."),
]
